import telebot
import random
import time
import base64
import logging
import os
import sys
import threading
import secrets
import string
from io import BytesIO
from threading import RLock
from datetime import datetime, timedelta, timezone

# ─────────────────────────────────────────────
BOT_TOKEN = os.getenv("BOT_TOKEN")
if not BOT_TOKEN:
    raise RuntimeError("BOT_TOKEN environment variable is missing. Set it in Pella app environment variables.")
# Each Telegram user gets their own auto-generated password and credits.
# Saved format:
# telegram_id|password|created_at|paid_credits|free_date|free_credits_left
BASE_DIR = os.path.dirname(os.path.abspath(__file__))
USER_PASSWORD_FILE = os.getenv("USER_PASSWORD_FILE", os.path.join(BASE_DIR, "user_passwords.txt"))
PASSWORD_LENGTH = 10
DAILY_FREE_CREDITS = 1
ADMIN_USERNAME = "RandomRidoy"   # Admin Telegram username without @
# ─────────────────────────────────────────────

# GMT +5:30 time zone
GMT_530 = timezone(timedelta(hours=5, minutes=30))

# ── Per-user password + credit storage ─────────────────────
user_passwords_lock = RLock()

def generate_user_password(length=PASSWORD_LENGTH):
    alphabet = string.ascii_uppercase + string.digits
    return "".join(secrets.choice(alphabet) for _ in range(length))

def today_gmt530():
    return now_gmt530().strftime("%Y-%m-%d")

def _normalize_user_record(parts):
    created_at = parts[2] if len(parts) > 2 and parts[2] else now_gmt530().strftime("%Y-%m-%d %H:%M:%S")
    try:
        paid_credits = int(parts[3]) if len(parts) > 3 and parts[3] else 0
    except ValueError:
        paid_credits = 0
    free_date = parts[4] if len(parts) > 4 and parts[4] else today_gmt530()
    try:
        free_left = int(parts[5]) if len(parts) > 5 and parts[5] else DAILY_FREE_CREDITS
    except ValueError:
        free_left = DAILY_FREE_CREDITS
    return {
        "password": parts[1],
        "created_at": created_at,
        "paid_credits": max(0, paid_credits),
        "free_date": free_date,
        "free_left": max(0, free_left),
    }

def load_user_passwords():
    users = {}
    if not os.path.exists(USER_PASSWORD_FILE):
        return users

    with open(USER_PASSWORD_FILE, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or "|" not in line:
                continue
            parts = line.split("|")
            if len(parts) >= 2:
                users[str(parts[0])] = _normalize_user_record(parts)
    return users

def save_user_passwords(users):
    tmp_file = USER_PASSWORD_FILE + ".tmp"
    with open(tmp_file, "w", encoding="utf-8") as f:
        for telegram_id, data in sorted(users.items(), key=lambda x: int(x[0]) if str(x[0]).isdigit() else str(x[0])):
            f.write(
                f"{telegram_id}|{data['password']}|{data.get('created_at', '')}|"
                f"{int(data.get('paid_credits', 0))}|{data.get('free_date', today_gmt530())}|"
                f"{int(data.get('free_left', DAILY_FREE_CREDITS))}\n"
            )
    os.replace(tmp_file, USER_PASSWORD_FILE)

def refresh_daily_free_credits(data):
    today = today_gmt530()
    if data.get("free_date") != today:
        data["free_date"] = today
        data["free_left"] = DAILY_FREE_CREDITS

def get_or_create_user(telegram_id):
    telegram_id = str(telegram_id)
    with user_passwords_lock:
        users = load_user_passwords()
        if telegram_id not in users:
            users[telegram_id] = {
                "password": generate_user_password(),
                "created_at": now_gmt530().strftime("%Y-%m-%d %H:%M:%S"),
                "paid_credits": 0,
                "free_date": today_gmt530(),
                "free_left": DAILY_FREE_CREDITS,
            }
        refresh_daily_free_credits(users[telegram_id])
        save_user_passwords(users)
        return dict(users[telegram_id])

def get_or_create_user_password(telegram_id):
    return get_or_create_user(telegram_id)["password"]

def user_exists(telegram_id):
    telegram_id = str(telegram_id)
    with user_passwords_lock:
        users = load_user_passwords()
        return telegram_id in users

def is_correct_user_password(telegram_id, password):
    telegram_id = str(telegram_id)
    with user_passwords_lock:
        users = load_user_passwords()
        if telegram_id not in users:
            return False
        refresh_daily_free_credits(users[telegram_id])
        save_user_passwords(users)
        return users[telegram_id]["password"] == password

def get_credit_summary(telegram_id):
    data = get_or_create_user(telegram_id)
    return int(data.get("free_left", 0)), int(data.get("paid_credits", 0))

def charge_one_credit(telegram_id):
    telegram_id = str(telegram_id)
    with user_passwords_lock:
        users = load_user_passwords()
        if telegram_id not in users:
            users[telegram_id] = {
                "password": generate_user_password(),
                "created_at": now_gmt530().strftime("%Y-%m-%d %H:%M:%S"),
                "paid_credits": 0,
                "free_date": today_gmt530(),
                "free_left": DAILY_FREE_CREDITS,
            }
        refresh_daily_free_credits(users[telegram_id])
        data = users[telegram_id]
        if int(data.get("free_left", 0)) > 0:
            data["free_left"] = int(data.get("free_left", 0)) - 1
            save_user_passwords(users)
            return True, "free"
        if int(data.get("paid_credits", 0)) > 0:
            data["paid_credits"] = int(data.get("paid_credits", 0)) - 1
            save_user_passwords(users)
            return True, "paid"
        save_user_passwords(users)
        return False, "none"

def add_paid_credits(telegram_id, amount):
    telegram_id = str(telegram_id)
    amount = int(amount)
    with user_passwords_lock:
        users = load_user_passwords()
        if telegram_id not in users:
            users[telegram_id] = {
                "password": generate_user_password(),
                "created_at": now_gmt530().strftime("%Y-%m-%d %H:%M:%S"),
                "paid_credits": 0,
                "free_date": today_gmt530(),
                "free_left": DAILY_FREE_CREDITS,
            }
        refresh_daily_free_credits(users[telegram_id])
        users[telegram_id]["paid_credits"] = max(0, int(users[telegram_id].get("paid_credits", 0)) + amount)
        save_user_passwords(users)
        return dict(users[telegram_id])

def is_admin(message):
    username = (getattr(message.from_user, "username", "") or "").lstrip("@")
    return username.lower() == ADMIN_USERNAME.lower()

def parse_admin_credit_command(text):
    # Format: 6332045896 +10 or 6332045896 -5
    parts = text.strip().split()
    if len(parts) != 2 or not parts[0].isdigit():
        return None
    if not (parts[1].startswith("+") or parts[1].startswith("-")):
        return None
    try:
        amount = int(parts[1])
    except ValueError:
        return None
    return parts[0], amount

