def get_session(cid):
    with sessions_lock:
        if cid not in sessions:
            sessions[cid] = {
                "state":     "awaiting_password",
                "broker":    None,
                "asset":     None,
                "timeframe": None,
                "count":     0,
            }
        return sessions[cid]

