# ── Signal builder ─────────────────────────────────

def build_conf_bar(pct):
    f = round(pct / 10)
    return "█" * f + "░" * (10 - f)

def msg_signal(s, direction, confidence, exec_time):
    conf_emoji = "🟢" if confidence >= 90 else "🟡"
    bar = build_conf_bar(confidence)
    now = now_gmt530().strftime("%b %d, %Y")
    sig_id = str(s["count"]).zfill(3)
    return (
        "⚡  *FUTURE — SIGNAL #" + sig_id + "*\n\n"
        "📌  *Asset:*       `" + s["asset"] + "`\n"
        "🏦  *Broker:*      `" + s["broker"] + "`\n"
        "⏱   *Timeframe:*  `" + s["timeframe"] + "`\n\n"
        + conf_emoji + "  *AI Guarantee:*\n"
        "     " + bar + "  `" + str(confidence) + "%`\n\n"
        "📅  *Date:*        `" + now + "`\n"
        "🎯  *Open At:*     `" + exec_time + "`\n"
        "🌐  *Time Zone:*   `GMT +5:30`\n\n"
        "━━━━━━━━━━━━━━━━━━━━━━━━━\n"
        "_Do Not Trade Against Momentum. Trade at your own risk._"
    )

# ── /start ─────────────────────────────────────────

@bot.message_handler(commands=["start"])
def cmd_start(message):
    cid = message.chat.id
    delete_previous_bot_messages(cid)
    s = get_session(cid)
    s.update({"state": "awaiting_password", "broker": None, "asset": None, "timeframe": None})

    is_new_user = not user_exists(cid)
    user_data = get_or_create_user(cid)
    free_left, paid_credits = get_credit_summary(cid)

    if is_new_user:
        start_text = (
            "*Safe Access Bot*\n\n"
            "✅  *New account created!*\n"
            "🔑  *Your password:* `" + user_data["password"] + "`\n\n"
            "Save this password. It will be shown only this first time.\n\n"
            "🆓  *Daily free credits left:* `" + str(free_left) + "`\n"
            "💳  *Paid credits:* `" + str(paid_credits) + "`\n\n"
            "Each bot action costs `1` credit. You get `1` free credits daily.\n"
            "Need more credits? Message admin: @" + ADMIN_USERNAME + "\n\n"
            "🔐  Enter your access *password* to continue:"
        )
    else:
        start_text = (
            "*Safe Access Bot*\n\n"
            "👋  Welcome back!\n\n"
            "🆓  *Daily free credits left:* `" + str(free_left) + "`\n"
            "💳  *Paid credits:* `" + str(paid_credits) + "`\n\n"
            "Your password is already saved. For safety, it is not shown again.\n"
            "Need more credits? Message admin: @" + ADMIN_USERNAME + "\n\n"
            "It does not constitute financial advice, investment advice, or trading recommendations.\nI am not responsible for any profits or losses that may occur as a result of your trading decisions. Trading in financial markets, including forex and cryptocurrencies, involves significant risk and may result in the loss of your entire capital. All trades shown or discussed are executed on personal accounts and are shared solely to explain strategies and market behavior. You should not copy or rely on these trades for your own decisions. Always conduct your own research, assess your risk tolerance, and perform due diligence before trading on any platform. Trade responsibly. You trade at your own risk.\n\n"
            "🔐  Enter your access *password* to continue:"
        )

    send_logo_message(
        cid,
        start_text,
        parse_mode="Markdown",
        reply_markup=telebot.types.ReplyKeyboardRemove()
    )

# ── Text handler (only for password) ──────────────

@bot.message_handler(func=lambda m: True)
def handle_text(message):
    cid  = message.chat.id
    text = (message.text or "").strip()
    s    = get_session(cid)

    admin_cmd = parse_admin_credit_command(text)
    if admin_cmd:
        if not is_admin(message):
            send_tracked_message(cid, "🚫  Only admin can add or remove credits.")
            return
        target_id, amount = admin_cmd
        data = add_paid_credits(target_id, amount)
        send_tracked_message(
            cid,
            "✅  *Credit updated!*\n\n"
            "👤  *Telegram ID:* `" + target_id + "`\n"
            "➕  *Change:* `" + str(amount) + "`\n"
            "💳  *Paid credits now:* `" + str(data.get("paid_credits", 0)) + "`",
            parse_mode="Markdown"
        )
        return

    if s["state"] == "awaiting_password":
        if is_correct_user_password(cid, text):
            s["state"] = "awaiting_broker"
            free_left, paid_credits = get_credit_summary(cid)
            send_tracked_message(
                cid,
                "✅  *Access granted!*\n\n"
                "🆓  *Daily free credits left:* `" + str(free_left) + "`\n"
                "💳  *Paid credits:* `" + str(paid_credits) + "`\n\n"
                "🏦  *Select your Broker:*",
                parse_mode="Markdown",
                reply_markup=kb_brokers()
            )
        else:
            send_tracked_message(
                cid,
                "🚫  *Wrong password!* Try again:",
                parse_mode="Markdown"
            )
    else:
        # If user types instead of tapping a button
        s["state"] = "awaiting_password"
        send_tracked_message(
            cid,
            "⚠️  Please use the buttons. Session reset.\n\nSend /start to begin again."
        )

