# ── Callback: Timeframe → Signal ───────────────────

@bot.callback_query_handler(func=lambda c: c.data.startswith("tf:"))
def cb_timeframe(call):
    cid = call.message.chat.id
    s   = get_session(cid)
    tf_raw = call.data.split(":", 1)[1]

    ok, charged_from = charge_one_credit(cid)
    if not ok:
        s["state"] = "awaiting_broker"
        bot.answer_callback_query(call.id, "No credits left")
        send_tracked_message(
            cid,
            "⚠️  *No credits left.*\n\n"
            "You get `1` free credits daily. For more credits, message admin: @" + ADMIN_USERNAME,
            parse_mode="Markdown"
        )
        return

    s["timeframe"] = TIMEFRAME_LABEL[tf_raw]
    s["state"]     = "done"
    s["count"]    += 1

    direction  = random.choice(["UP", "DOWN"])
    confidence = random.randint(80, 100)
    exec_time  = (now_gmt530() + timedelta(minutes=1)).strftime("%H:%M")
    free_left, paid_credits = get_credit_summary(cid)

    bot.answer_callback_query(call.id, "1 credit used")
    bot.edit_message_text(
        "⏱  *Timeframe:* `" + s["timeframe"] + "` ✅",
        cid, call.message.message_id,
        parse_mode="Markdown"
    )
    send_tracked_message(cid, "⏳  *Analyzing market data...*", parse_mode="Markdown")
    bot.send_chat_action(cid, "typing")
    time.sleep(1.5)
    send_signal_photo_message(
        cid,
        direction,
        msg_signal(s, direction, confidence, exec_time) +
        "\n\n💳  *Charged:* `1` credit (`" + charged_from + "`)" +
        "\n🆓  *Daily free left:* `" + str(free_left) + "`" +
        "\n💳  *Paid credits left:* `" + str(paid_credits) + "`",
        parse_mode="Markdown",
        reply_markup=kb_again()
    )

# ── Callback: After signal ─────────────────────────

@bot.callback_query_handler(func=lambda c: c.data.startswith("action:"))
def cb_action(call):
    cid    = call.message.chat.id
    s      = get_session(cid)
    action = call.data.split(":", 1)[1]

    if action == "new":
        s.update({"state": "awaiting_broker", "broker": None, "asset": None, "timeframe": None})
        bot.answer_callback_query(call.id, "Starting new signal...")
        delete_previous_bot_messages(cid)
        send_tracked_message(
            cid,
            "🏦  *Select your Broker:*",
            parse_mode="Markdown",
            reply_markup=kb_brokers()
        )
    elif action == "exit":
        s.update({"state": "awaiting_password", "broker": None, "asset": None, "timeframe": None})
        bot.answer_callback_query(call.id, "Session ended.")
        send_tracked_message(
            cid,
            "🔴  *Session ended.*\n\nSend /start to begin again.",
            parse_mode="Markdown"
        )

# ── Keep-alive web server for hosts that expect an HTTP port ────────────────
def start_keep_alive_server():
    """Starts a tiny health-check server when Flask is available.

    Some hosting panels stop apps that do not bind to a web port. The bot still
    uses Telegram long polling; this server only proves to the host that the app
    is alive.
    """
    try:
        from flask import Flask
        from werkzeug.serving import make_server
    except Exception:
        logging.info("Flask is not installed; skipping HTTP keep-alive server.")
        return

    app = Flask(__name__)

    @app.get("/")
    def home():
        return "Bot is running", 200

    @app.get("/health")
    def health():
        return "OK", 200

    port = int(os.getenv("PORT", "8080"))

    def run_server():
        try:
            server = make_server("0.0.0.0", port, app)
            logging.info("Keep-alive server started on port %s", port)
            server.serve_forever()
        except Exception:
            logging.exception("Keep-alive server crashed")

    threading.Thread(target=run_server, daemon=True).start()


def run_bot_forever():
    """Run Telegram polling forever and restart it after recoverable crashes."""
    retry_delay = 5
    max_delay = 60

    while True:
        try:
            logging.info("QUOTEX FUTURE BOT STARTING...")

            # Some Pella/pyTelegramBotAPI versions do not support
            # remove_webhook(drop_pending_updates=True), so use a safe fallback.
            try:
                bot.remove_webhook()
            except Exception:
                logging.exception("Could not remove webhook before polling")

            # Start polling. If the installed telebot version does not support
            # newer keyword arguments, fall back to the older compatible call.
            try:
                bot.infinity_polling(
                    timeout=30,
                    long_polling_timeout=30,
                    skip_pending=True,
                    allowed_updates=["message", "callback_query"],
                    logger_level=logging.INFO,
                )
            except TypeError:
                logging.exception("Current telebot version rejected a polling option; using compatibility mode")
                bot.infinity_polling(
                    timeout=30,
                    long_polling_timeout=30,
                )

            logging.warning("Polling stopped without an exception; restarting in %s seconds", retry_delay)
        except KeyboardInterrupt:
            logging.info("Bot stopped by KeyboardInterrupt")
            break
        except Exception:
            logging.exception("Polling crashed; restarting in %s seconds", retry_delay)

        time.sleep(retry_delay)
        retry_delay = min(max_delay, retry_delay * 2)


# ── Run ────────────────────────────────────────────
if __name__ == "__main__":
    start_keep_alive_server()
    run_bot_forever()
